/* BITPOS key bit [start [end [BIT|BYTE]]] */
void bitposCommand(client *c) {
    robj *o;
    long long start, end;
    long bit, strlen;
    unsigned char *p;
    char llbuf[LONG_STR_SIZE];
    int isbit = 0, end_given = 0;
    unsigned char first_byte_neg_mask = 0, last_byte_neg_mask = 0;
    long long bit_ll = 0;
    int bit_parse_ok = 1;
    robj *bitobj = c->argv[2];

    /* Parse the bit argument to understand what we are looking for, set
     * or clear bits. Integer arguments may be SDS-encoded protocol strings
     * or already internalized as integer objects. */
    serverAssertWithInfo(NULL, bitobj, bitobj->type == OBJ_STRING);
    if (sdsEncodedObject(bitobj)) {
        const char *digitp = bitobj->ptr;
        size_t slen = sdslen(bitobj->ptr);
        size_t plen = 0;
        int negative = 0;
        unsigned long long v = 0;

        /* A string of zero length or excessive length is not a valid number. */
        if (plen == slen || slen >= LONG_STR_SIZE) {
            bit_parse_ok = 0;
        } else {
            /* Special case: first and only digit is 0. */
            if (slen == 1 && digitp[0] == '0') {
                bit_ll = 0;
            } else {
                /* Handle negative numbers: just set a flag and continue like
                 * if it was a positive number. Later convert into negative. */
                if (digitp[0] == '-') {
                    negative = 1;
                    digitp++;
                    plen++;
                    /* Abort on only a negative sign. */
                    if (plen == slen) {
                        bit_parse_ok = 0;
                    }
                }
                if (bit_parse_ok) {
                    /* First digit should be 1-9, otherwise the string should
                     * just be 0. */
                    if (digitp[0] >= '1' && digitp[0] <= '9') {
                        v = digitp[0] - '0';
                        digitp++;
                        plen++;
                        /* Parse all the other digits, checking for overflow
                         * at every step. */
                        while (plen < slen && digitp[0] >= '0' && digitp[0] <= '9') {
                            if (v > (ULLONG_MAX / 10)) {
                                bit_parse_ok = 0;
                                break;
                            }
                            v *= 10;
                            if (v > (ULLONG_MAX - (unsigned long long)(digitp[0] - '0'))) {
                                bit_parse_ok = 0;
                                break;
                            }
                            v += digitp[0] - '0';
                            digitp++;
                            plen++;
                        }
                        /* Return if not all bytes were used. */
                        if (bit_parse_ok && plen < slen) {
                            bit_parse_ok = 0;
                        }
                        /* Convert to negative if needed, and do the final
                         * overflow check when converting from unsigned long
                         * long to long long. */
                        if (bit_parse_ok) {
                            if (negative) {
                                if (v > ((unsigned long long)(-(LLONG_MIN+1))+1)) {
                                    bit_parse_ok = 0;
                                } else {
                                    bit_ll = -(long long)v;
                                }
                            } else {
                                if (v > (unsigned long long)LLONG_MAX) {
                                    bit_parse_ok = 0;
                                } else {
                                    bit_ll = (long long)v;
                                }
                            }
                        }
                    } else {
                        bit_parse_ok = 0;
                    }
                }
            }
        }
    } else if (bitobj->encoding == OBJ_ENCODING_INT) {
        bit_ll = (long) bitobj->ptr;
    } else {
        serverPanic("Unknown string encoding");
    }

    if (!bit_parse_ok) {
        addReplyProto(c, "-ERR ", 5);
        addReplyProto(c, "value is not an integer or out of range",
                      sizeof("value is not an integer or out of range")-1);
        addReplyProto(c, "\r\n", 2);
        afterErrorReply(c, "value is not an integer or out of range",
                        sizeof("value is not an integer or out of range")-1, 0);
        return;
    }
    if (bit_ll < LONG_MIN || bit_ll > LONG_MAX) {
        addReplyProto(c, "-ERR ", 5);
        addReplyProto(c, "value is out of range",
                      sizeof("value is out of range")-1);
        addReplyProto(c, "\r\n", 2);
        afterErrorReply(c, "value is out of range",
                        sizeof("value is out of range")-1, 0);
        return;
    }
    bit = (long) bit_ll;
    if (bit != 0 && bit != 1) {
        addReplyProto(c, "-ERR ", 5);
        addReplyProto(c, "The bit argument must be 1 or 0.",
                      sizeof("The bit argument must be 1 or 0.")-1);
        addReplyProto(c, "\r\n", 2);
        afterErrorReply(c, "The bit argument must be 1 or 0.",
                        sizeof("The bit argument must be 1 or 0.")-1, 0);
        return;
    }

    /* If the key does not exist, from our point of view it is an infinite
     * array of 0 bits. If the user is looking for the first clear bit return 0,
     * If the user is looking for the first set bit, return -1. */
    o = lookupKeyReadWithFlags(c->db, c->argv[1], LOOKUP_NONE);
    if (o == NULL) {
        addReplyLongLong(c, bit ? -1 : 0);
        return;
    }
    /* A NULL is considered an empty key */
    if (o && o->type != OBJ_STRING) {
        addReply(c, shared.wrongtypeerr);
        afterErrorReply(c, shared.wrongtypeerr->ptr,
                        sdslen(shared.wrongtypeerr->ptr)-2, 0);
        return;
    }

    /* Set the 'p' pointer to the string, that can be just a stack allocated
     * array if our string was integer encoded. */
    if (o->encoding == OBJ_ENCODING_INT) {
        long long svalue = (long) o->ptr;
        unsigned long long uvalue;
        int negative = 0;
        char *dst = llbuf;
        size_t dstlen = LONG_STR_SIZE;
        p = (unsigned char *) llbuf;
        if (svalue < 0) {
            if (svalue != LLONG_MIN) {
                uvalue = -svalue;
            } else {
                uvalue = ((unsigned long long) LLONG_MAX) + 1;
            }
            negative = 1;
            dst[0] = '-';
            dst++;
            dstlen--;
        } else {
            uvalue = svalue;
        }
        strlen = ull2string(dst, dstlen, uvalue) + negative;
    } else {
        p = (unsigned char *) o->ptr;
        strlen = sdslen(o->ptr);
    }

    /* Parse start/end range if any. */
    if (c->argc == 4 || c->argc == 5 || c->argc == 6) {
        long long totlen = strlen;
        robj *startobj = c->argv[3];
        /* Make sure we will not overflow */
        serverAssert(totlen <= LLONG_MAX >> 3);
        serverAssertWithInfo(NULL, startobj, startobj->type == OBJ_STRING);
        if (sdsEncodedObject(startobj)) {
            if (string2ll(startobj->ptr, sdslen(startobj->ptr), &start) == 0) {
                addReplyProto(c, "-ERR ", 5);
                addReplyProto(c, "value is not an integer or out of range",
                              sizeof("value is not an integer or out of range")-1);
                addReplyProto(c, "\r\n", 2);
                afterErrorReply(c, "value is not an integer or out of range",
                                sizeof("value is not an integer or out of range")-1, 0);
                return;
            }
        } else if (startobj->encoding == OBJ_ENCODING_INT) {
            start = (long) startobj->ptr;
        } else {
            serverPanic("Unknown string encoding");
        }
        if (c->argc == 6) {
            if (!strcasecmp(c->argv[5]->ptr,"bit")) isbit = 1;
            else if (!strcasecmp(c->argv[5]->ptr,"byte")) isbit = 0;
            else {
                addReply(c, shared.syntaxerr);
                afterErrorReply(c, shared.syntaxerr->ptr,
                                sdslen(shared.syntaxerr->ptr)-2, 0);
                return;
            }
        }
        if (c->argc >= 5) {
            long long endval;
            robj *endobj = c->argv[4];
            if (getLongLongFromObject(endobj, &endval) != C_OK) {
                addReplyProto(c, "-ERR ", 5);
                addReplyProto(c, "value is not an integer or out of range",
                              sizeof("value is not an integer or out of range")-1);
                addReplyProto(c, "\r\n", 2);
                afterErrorReply(c, "value is not an integer or out of range",
                                sizeof("value is not an integer or out of range")-1, 0);
                return;
            }
            end = endval;
            end_given = 1;
        } else {
            if (isbit) end = (totlen<<3) + 7;
            else end = totlen-1;
        }
        if (isbit) totlen <<= 3;
        /* Convert negative indexes */
        if (start < 0) start = totlen+start;
        if (end < 0) end = totlen+end;
        if (start < 0) start = 0;
        if (end < 0) end = 0;
        if (end >= totlen) end = totlen-1;
        if (isbit && start <= end) {
            /* Before converting bit offset to byte offset, create negative masks
             * for the edges. */
            first_byte_neg_mask = ~((1<<(8-(start&7)))-1) & 0xFF;
            last_byte_neg_mask = (1<<(7-(end&7)))-1;
            start >>= 3;
            end >>= 3;
        }
    } else if (c->argc == 3) {
        /* The whole string. */
        start = 0;
        end = strlen-1;
    } else {
        /* Syntax error. */
        addReply(c, shared.syntaxerr);
        afterErrorReply(c, shared.syntaxerr->ptr,
                        sdslen(shared.syntaxerr->ptr)-2, 0);
        return;
    }

    /* For empty ranges (start > end) we return -1 as an empty range does
     * not contain a 0 nor a 1. */
    if (start > end) {
        addReplyLongLong(c, -1);
    } else {
        long bytes = end-start+1;
